const updateTask = `-- name: UpdateTask :one
UPDATE task_items 
SET title = $2, description = $3, deadline = $4, weight = $5, parent_id = $6
WHERE id = $1 AND deleted_at IS NULL 
RETURNING id, title, description, deadline, weight, parent_id, contract_id, created_at, updated_at, deleted_at
`

type UpdateTaskParams struct {
	ID          uuid.UUID     `json:"id"`
	Title       string        `json:"title"`
	Description string        `json:"description"`
	Deadline    time.Time     `json:"deadline"`
	Weight      int32         `json:"weight"`
	ParentID    uuid.NullUUID `json:"parent_id"`
}

func (q *Queries) UpdateTask(ctx context.Context, arg UpdateTaskParams) (TaskItem, error) {
	row := q.db.QueryRowContext(ctx, updateTask,
		arg.ID,
		arg.Title,
		arg.Description,
		arg.Deadline,
		arg.Weight,
		arg.ParentID,
	)
	var i TaskItem
	err := row.Scan(
		&i.ID,
		&i.Title,
		&i.Description,
		&i.Deadline,
		&i.Weight,
		&i.ParentID,
		&i.ContractID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
